CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor matmul_with_transposed_both(torch::Tensor A, torch::Tensor B);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("matmul_with_transposed_both", &matmul_with_transposed_both, "Matmul with both inputs logically transposed (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/ATen.h>

// Tiled GEMM for C = A^T @ B^T
// A: (M, K) stored row-major, A^T is (K, M)
// B: (K, N) stored row-major, B^T is (N, K)
// C: (K, N) ... wait, let me re-check:
// A shape: (M_a, K_a), B shape: (K_b, N_b)
// C = A^T @ B^T => C shape: (K_a, K_b) ... no
// A is (M, K), A^T is (K, M)
// B is (K, N), B^T is (N, K)
// C = A^T @ B^T = (K,M) @ (N,K) -- this doesn't work dimensionally unless M==K of second
// Actually for the benchmark: A=(8192,2048), B=(4096,8192)
// A^T = (2048, 8192), B^T = (8192, 4096)
// C = A^T @ B^T = (2048, 8192) @ (8192, 4096) = (2048, 4096)
// So M_out=A.size(1)=2048, N_out=B.size(0)=4096, K_inner=A.size(0)=B.size(1)=8192
// C[i,j] = sum_{k=0}^{K-1} A^T[i,k] * B^T[k,j]
//         = sum_{k=0}^{K-1} A[k,i] * B[j,k]
// A[k,i]: row=k, col=i in A (row-major: index = k*K_a + i, K_a=A.size(1))
// B[j,k]: row=j, col=k in B (row-major: index = j*K_b + k, K_b=B.size(1))

#define TILE 32
#define PAD 1

__global__ void matmul_tt_kernel(
    const float* __restrict__ A,  // (M, Ka) = (8192, 2048)
    const float* __restrict__ B,  // (Kb, N) = (4096, 8192)
    float* __restrict__ C,        // (Ka, Kb) = (2048, 4096)
    int M,   // A.size(0) = 8192 = K_inner
    int Ka,  // A.size(1) = 2048 = M_out
    int Kb   // B.size(0) = 4096 = N_out
    // B.size(1) must equal M = 8192
) {
    // C[i,j] = sum_k A[k,i] * B[j,k]
    // i in [0, Ka), j in [0, Kb)
    // blockIdx.x -> tile of i (M_out dimension)
    // blockIdx.y -> tile of j (N_out dimension)
    int i_base = blockIdx.x * TILE;
    int j_base = blockIdx.y * TILE;
    int tx = threadIdx.x;  // col within tile (j direction)
    int ty = threadIdx.y;  // row within tile (i direction)

    int i = i_base + ty;
    int j = j_base + tx;

    // Shared memory tiles with padding to avoid bank conflicts
    __shared__ float sA[TILE][TILE + PAD];  // sA[ty][tk]: A[k_base+tk, i_base+ty] = A[(k_base+tk)*Ka + (i_base+ty)]
    __shared__ float sB[TILE][TILE + PAD];  // sB[tx][tk]: B[j_base+tx, k_base+tk] = B[(j_base+tx)*M + (k_base+tk)]

    float acc = 0.0f;

    int num_tiles = (M + TILE - 1) / TILE;
    for (int t = 0; t < num_tiles; t++) {
        int k_base = t * TILE;

        // Load sA: sA[ty][tx] = A[(k_base+tx)*Ka + i]
        // thread (ty, tx) loads A[k_base+tx, i_base+ty]
        int k_a = k_base + tx;
        if (k_a < M && i < Ka)
            sA[ty][tx] = A[k_a * Ka + i];
        else
            sA[ty][tx] = 0.0f;

        // Load sB: sB[tx][ty] = B[(j_base+tx)*M + (k_base+ty)]
        // thread (ty, tx) loads B[j_base+tx, k_base+ty]
        int k_b = k_base + ty;
        if (j < Kb && k_b < M)
            sB[tx][ty] = B[j * M + k_b];
        else
            sB[tx][ty] = 0.0f;

        __syncthreads();

        // Compute: acc += sum_{tk=0}^{TILE-1} sA[ty][tk] * sB[tx][tk]
        #pragma unroll
        for (int tk = 0; tk < TILE; tk++) {
            acc += sA[ty][tk] * sB[tx][tk];
        }

        __syncthreads();
    }

    if (i < Ka && j < Kb) {
        C[i * Kb + j] = acc;
    }
}

torch::Tensor matmul_with_transposed_both(torch::Tensor A, torch::Tensor B) {
    // Fast path: float32, 2D, CUDA
    if (A.is_cuda() && B.is_cuda() &&
        A.dtype() == torch::kFloat32 && B.dtype() == torch::kFloat32 &&
        A.dim() == 2 && B.dim() == 2 &&
        A.size(0) == B.size(1)) {

        int M   = (int)A.size(0);   // K_inner = 8192
        int Ka  = (int)A.size(1);   // M_out   = 2048
        int Kb  = (int)B.size(0);   // N_out   = 4096

        auto C = torch::empty({Ka, Kb}, A.options());

        dim3 block(TILE, TILE);
        dim3 grid((Ka + TILE - 1) / TILE, (Kb + TILE - 1) / TILE);

        matmul_tt_kernel<<<grid, block>>>(
            A.data_ptr<float>(),
            B.data_ptr<float>(),
            C.data_ptr<float>(),
            M, Ka, Kb
        );

        return C;
    }
    // Fallback
    return at::matmul(A.transpose(0, 1), B.transpose(0, 1));
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a single matrix multiplication (C = A * B)
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        if not (A.is_cuda and B.is_cuda):
                    return torch.matmul(A.T, B.T)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return _stark_get_extension().matmul_with_transposed_both(A, B)
        # <<<END_IMPROVE>>>

