CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor matmul_with_transposed_both_cuda(torch::Tensor A, torch::Tensor B);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("matmul_with_transposed_both_cuda", &matmul_with_transposed_both_cuda,
        "Matmul with both inputs logically transposed (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <ATen/cuda/CUDAContext.h>

// Transpose kernel: reads src[rows x cols] row-major, writes dst[cols x rows] row-major
__global__ void transpose_kernel(const float* __restrict__ src, float* __restrict__ dst,
                                  int rows, int cols) {
    __shared__ float tile[32][33];
    int bx = blockIdx.x * 32;
    int by = blockIdx.y * 32;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int r = by + ty;
    int c = bx + tx;
    if (r < rows && c < cols)
        tile[ty][tx] = src[r * cols + c];
    __syncthreads();
    // write transposed
    int wr = bx + ty;
    int wc = by + tx;
    if (wr < cols && wc < rows)
        dst[wr * rows + wc] = tile[tx][ty];
}

torch::Tensor matmul_with_transposed_both_cuda(torch::Tensor A, torch::Tensor B) {
    // A: (M, K), B: (K_b, N) where K_b == M for the problem
    // We want C = A.T @ B.T  =>  C = (B @ A).T
    // B: (K_b, N), A: (M, K)
    // B @ A => shape (K_b, K) -- but wait, let's be precise:
    // A shape: (M, K), B shape: (K_b, N)
    // A.T: (K, M), B.T: (N, K_b)
    // A.T @ B.T: (K, M) @ (N, K_b) -- this only works if M == N
    // Actually for this problem: A=(8192,2048), B=(4096,8192)
    // A.T=(2048,8192), B.T=(8192,4096)
    // A.T @ B.T = (2048,8192)@(8192,4096) = (2048,4096)
    // Identity: (A.T @ B.T) = (B @ A).T
    // B @ A = (4096,8192)@(8192,2048) = (4096,2048)
    // (B @ A).T = (2048,4096) â

    if (!A.is_cuda() || !B.is_cuda() || A.scalar_type() != torch::kFloat32 ||
        B.scalar_type() != torch::kFloat32 || A.dim() != 2 || B.dim() != 2) {
        return at::matmul(A.t(), B.t());
    }

    int64_t M = A.size(0), K = A.size(1);
    int64_t Kb = B.size(0), N = B.size(1);
    // Need K == N for B @ A to work: B(Kb,N) @ A(M,K) => Kb x M, need N==K
    if (K != N) {
        return at::matmul(A.t(), B.t());
    }

    // Ensure contiguous
    auto Ac = A.contiguous();
    auto Bc = B.contiguous();

    // Allocate temp for B @ A: shape (Kb, M)
    auto tmp = torch::empty({Kb, M}, A.options());
    // Allocate output: shape (M, Kb) = (A.T @ B.T) shape
    auto out = torch::empty({M, Kb}, A.options());

    cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();

    // cuBLAS is column-major. We have row-major tensors.
    // We want: tmp = B @ A  (Kb x M)
    // In col-major terms: tmp^T = A^T @ B^T
    // tmp^T is (M x Kb) col-major
    // A^T is (K x M) col-major = A row-major (M x K) interpreted as col-major (K x M)
    // B^T is (N x Kb) col-major = B row-major (Kb x N) interpreted as col-major (N x Kb)
    // We want C = op(A) @ op(B) in col-major
    // C(M x Kb) = A_colmaj(K x M)^T @ B_colmaj(N x Kb)^T
    // => cublasSgemm(handle, CUBLAS_OP_T, CUBLAS_OP_T, M, Kb, K,
    //               alpha, A_ptr, K, B_ptr, Kb, beta, tmp_ptr, M)
    // Wait, let me redo:
    // cublasSgemm computes C = alpha * op(A) * op(B) + beta * C
    // All in column-major.
    // We want tmp (Kb x M) row-major = B (Kb x N) row-major @ A (M x K) row-major
    // Treat row-major X(r,c) as col-major X^T.
    // So B row-major (Kb x N) = col-major B^T (N x Kb)
    //    A row-major (M x K)  = col-major A^T (K x M)
    //    tmp row-major (Kb x M) = col-major tmp^T (M x Kb)
    // We want tmp^T (M x Kb) col-major = A^T (K x M)^T col-major @ B^T (N x Kb)^T col-major
    //                                   = A_rowmaj @ B_rowmaj  -- no that's wrong
    // Let me use the standard trick:
    // To compute C_row = A_row @ B_row using cublas col-major:
    // C_col^T = A_col^T @ B_col^T
    // => C_col = B_col @ A_col  (swap order)
    // cublasSgemm(handle, CUBLAS_OP_N, CUBLAS_OP_N, cols_C, rows_C, inner,
    //             alpha, B_ptr, ldb, A_ptr, lda, beta, C_ptr, ldc)
    // For tmp = B @ A (Kb x M):
    //   rows_C = Kb, cols_C = M, inner = N(=K)
    //   In col-major: tmp_col (M x Kb) = A_col (M x K) @ B_col (K x Kb)
    //   => cublasSgemm(N, N, M, Kb, K, alpha, A_ptr, M, B_ptr, K, beta, tmp_ptr, M)
    //   lda = M (leading dim of A col-major = rows of A col-major = M)
    //   ldb = K (leading dim of B col-major = rows of B col-major = K = N)
    //   ldc = M
    float alpha = 1.0f, beta = 0.0f;
    cublasSgemm(handle,
                CUBLAS_OP_N, CUBLAS_OP_N,
                (int)M, (int)Kb, (int)K,
                &alpha,
                Ac.data_ptr<float>(), (int)M,
                Bc.data_ptr<float>(), (int)K,
                &beta,
                tmp.data_ptr<float>(), (int)M);
    // tmp is now (Kb x M) row-major = B @ A
    // We need out = tmp.T = (M x Kb) row-major
    // Launch transpose kernel
    dim3 block(32, 32);
    dim3 grid((int)((M + 31) / 32), (int)((Kb + 31) / 32));
    transpose_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        tmp.data_ptr<float>(), out.data_ptr<float>(), (int)Kb, (int)M);
    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a single matrix multiplication (C = A * B)
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Performs matrix multiplication.

                Args:
                    A: Input tensor of shape (M, K).
                    B: Input tensor of shape (K, N).

                Returns:
                    Output tensor of shape (M, N).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if A.is_cuda and B.is_cuda:
            return _stark_get_extension().matmul_with_transposed_both_cuda(A, B)
        return torch.matmul(A.T, B.T)
        # <<<END_IMPROVE>>>

