CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/ATen.h>

torch::Tensor matmul_with_transposed_both(torch::Tensor A, torch::Tensor B) {
    // C = A^T @ B^T  where A:(M,K), B:(N,M)  =>  C:(K,N)
    // Equivalent to: C^T = B @ A, so C = (B @ A)^T
    // We allocate C with transposed strides so that C^T is contiguous,
    // then call mm_out(C^T, B, A) which computes B @ A into C^T,
    // and return C which is logically (K, N).
    if (A.is_cuda() && B.is_cuda() &&
        A.scalar_type() == torch::kFloat32 &&
        B.scalar_type() == torch::kFloat32 &&
        A.dim() == 2 && B.dim() == 2 &&
        A.size(0) == B.size(1)) {

        int64_t K = A.size(1);  // output rows
